  'help.send': 'Odoslať tiket',
  'help.ticketSent': 'Tiket odoslaný!',
  'help.ticketSentDesc': 'Dostali sme tvoju žiadosť. Náš tím odpovie e-mailom do 24 hodín.',
  'help.close': 'Zavrieť',
  'help.ticketError': 'Nepodarilo sa odoslať tiket. Skús to znova.',
  'help.type.cant_login': 'Nemôžem sa prihlásiť',
  'help.type.email_issue': 'Problém s e-mailom',
  'help.type.security': 'Bezpečnosť',
  'help.type.other': 'Iné',
  'help.faq.cantLogin.q': 'Nemôžem sa prihlásiť do svojho účtu',
  'help.faq.cantLogin.a': 'Skontroluj, či používaš správny e-mail a heslo. Ak si zabudol heslo, klikni na "Zabudol si heslo?" na prihlasovacej obrazovke. Ak problém pretrváva, vytvor tiket podpory.',
  'help.faq.notReceiving.q': 'Nedostávam e-maily',
  'help.faq.notReceiving.a': 'Najprv skontroluj priečinok Spam. Uisti sa, že tvoj úložný priestor nie je plný. Ak problém pretrváva, potvrď, že odosielateľ má správnu adresu a vytvor tiket.',
  'help.faq.cantSend.q': 'Nemôžem odoslať e-maily',
  'help.faq.cantSend.a': 'Skontroluj svoje pripojenie na internet a či je adresa príjemcu správna. Skontroluj, či prílohy nepresahujú 25MB. Skús to znova o pár minút.',
  'help.faq.forgotPassword.q': 'Zabudol som svoje heslo',
  'help.faq.forgotPassword.a': 'Na prihlasovacej obrazovke klikni na "Zabudol si heslo?" a riaď sa pokynmi na obnovenie hesla cez e-mail.',
  'help.faq.accountSecurity.q': 'Myslím, že môj účet bol ohrozený',
  'help.faq.accountSecurity.a': 'Okamžite zmeň svoje heslo. Skontroluj priečinok Odoslané na správy, ktoré si neodoslal. Aktivuj dvojfaktorovú autentifikáciu v Nastaveniach > Bezpečnosť. Ak je to potrebné, vytvor urgentný tiket.',
  'help.faq.appAccess.q': 'Ako sa dostanem do aplikácie na mobile?',
  'help.faq.appAccess.a': 'Môžeš pristupovať k Chatyy cez prehliadač na chatyy.com.br, alebo si stiahnuť našu aplikáciu z obchodu s aplikáciami na tvojom zariadení.',
  'privacy.title': 'Zásady ochrany osobných údajov',
  'privacy.subtitle': 'Ako chránime a spracovávame tvoje údaje',
  'privacy.lastUpdated': 'Posledná aktualizácia: Marec 2026',
  'privacy.dataCollection.title': 'Zber údajov',
  'privacy.dataCollection.body': 'Zbierame len potrebné informácie pre službu e-mail: tvoje meno, e-mailovú adresu a obsah odoslaných a prijatých správ. Nepredávame ani nezdieľame tvoje osobné údaje s tretími stranami na marketingové účely.',
  'privacy.dataUsage.title': 'Ako používame tvoje údaje',
  'privacy.dataUsage.body': 'Tvoje údaje sú používané výhradne na prevádzku a zlepšovanie služby e-mail, vrátane doručovania správ, filtrovania spamu, funkcií AI (s tvojím súhlasom) a bezpečnosti účtu.',
  'privacy.dataSecurity.title': 'Bezpečnosť údajov',
  'privacy.dataSecurity.body': 'Používame priemyselnú štandardnú šifrovanie (TLS/SSL) pre všetky údaje v prenose a v pokoji. Relácie sú chránené šifrovanými tokenmi a ochranou CSRF. Pravidelne audítujeme naše bezpečnostné praktiky.',
  'privacy.cookies.title': 'Cookies a miestne úložisko',
  'privacy.cookies.body': 'Používame nevyhnutné cookies a miestne úložisko na udržanie tvojej relácie, zapamätanie tvojich preferencií (tému, jazyk) a poskytnutie plynulej skúsenosti. Nepoužívame cookies od tretích strán na sledovanie.',
  'privacy.thirdParties.title': 'Služby tretích strán',
  'privacy.thirdParties.body': 'Môžeme používať služby tretích strán pre špecifické funkcie ako AI (Anthropic Claude) a push notifikácie. Tieto služby dodržiavajú svoje vlastné zásady ochrany osobných údajov a spracovávajú len minimum potrebných údajov.',
  'privacy.rights.title': 'Tvoje práva',
  'privacy.rights.body': 'Máš právo kedykoľvek pristupovať, opravovať, exportovať alebo mazať svoje osobné údaje. Môžeš spravovať svoje údaje v Nastaveniach alebo kontaktovaním našej podpory.',
  'privacy.contact.title': 'Kontaktuj nás',
  'privacy.contact.body': 'Pre otázky týkajúce sa ochrany osobných údajov alebo žiadosti o údaje, kontaktuj nás na privacy@chatyy.com.br. Odpovieme do 30 dní.',
  'terms.title': 'Podmienky služby',
  'terms.subtitle': 'Pokyny na používanie Chatyy',
  'terms.lastUpdated': 'Posledná aktualizácia: Marec 2026',
  'terms.acceptance.title': 'Akceptácia podmienok',
  'terms.acceptance.body': 'Prístupom alebo používaním Chatyy súhlasíš s týmito podmienkami služby. Ak nesúhlasíš s ktoroukoľvek časťou týchto podmienok, nepoužívaj službu.',
  'terms.services.title': 'Popis služieb',
  'terms.services.body': 'Chatyy poskytuje služby komunikácie prostredníctvom e-mailu vrátane odosielania, prijímania a správy e-mailov, ako aj funkcií AI, integrácie s kalendárom a videokonferencií.',
  'terms.accounts.title': 'Účty používateľov',
  'terms.accounts.body': 'Ty si zodpovedný za udržanie bezpečnosti svojich prihlasovacích údajov. Nezdieľaj svoje heslo ani nedovoľuj neoprávnený prístup k svojmu účtu. Musíš mať aspoň 13 rokov na používanie tejto služby.',
  'terms.conduct.title': 'Prijateľné používanie',
  'terms.conduct.body': 'Súhlasíš s tým, že nebudeš používať službu na odosielanie spamu, malvéru, phishingu alebo akéhokoľvek nezákonného obsahu. Nepokúšaj sa získať prístup k účtom iných používateľov ani narušovať infraštruktúru služby.',
  'terms.content.title': 'Vlastníctvo obsahu',
  'terms.content.body': 'Zachovávaš si vlastníctvo nad všetkým obsahom, ktorý vytváraš a odosielaš prostredníctvom služby. Neprihlasujeme si vlastníctvo nad tvojimi e-mailmi alebo prílohami. Môžeme spracovávať obsah podľa potreby na poskytovanie služby.',
  'terms.limitation.title': 'Obmedzenie zodpovednosti',
  'terms.limitation.body': 'Chatyy je poskytovaný "tak, ako je". Usilujeme sa o 99,9% dostupnosť, ale nezaručujeme nepretržitú službu. Nie sme zodpovední za nepriame, náhodné alebo následné škody vyplývajúce z používania služby.',
  'terms.termination.title': 'Ukončenie účtu',
  'terms.termination.body': 'Môžeme pozastaviť alebo ukončiť účty, ktoré porušujú tieto podmienky. Svoj účet môžeš kedykoľvek zmazať v Nastaveniach. Po ukončení budú tvoje údaje zmazané do 30 dní.',
  'terms.changes.title': 'Zmeny v podmienkach',
  'terms.changes.body': 'Môžeme tieto podmienky pravidelne aktualizovať. O významných zmenách ťa budeme informovať e-mailom alebo notifikáciou v aplikácii. Pokračovanie v používaní po zmenách predstavuje akceptáciu aktualizovaných podmienok.',
