  'plans.faqWhatIsPlus': 'Čo je Chatyy One?',
  'plans.faqWhatIsPlusAnswer': 'Je to prémiový plán Chatyy, ktorý chráni všetky tvoje konverzácie, fotky a videá. S Chatyy One, aj keď niečo omylom vymažeš, môžeš to obnoviť do 30 dní. Okrem toho získaš 200GB úložiska, One AI ako osobného asistenta a môžeš posielať súbory až do 100MB.',
  'plans.faqCancelAnswer': 'Tvoj plán zostáva aktívny do konca zaplateného obdobia. Potom sa vrátiš k bezplatnému plánu. Tvoje fotky a videá, ktoré presahujú 15GB, budú uchované ešte 30 dní, aby si si ich mohol stiahnuť.',
  'plans.faqHowFamily': 'Ako funguje Pro plán?',
  'plans.faqHowFamilyAnswer': 'Môžeš pridať až 4 osoby zo svojej rodiny. Všetci zdieľajú 500GB úložiska a dostávajú všetky výhody Chatyy One. Každý má svoj súkromný priestor — nikto nevidí súbory ostatných.',
  'plans.faqChangePlanAnswer': 'Áno! Ak urobíš upgrade z Plus na Pro, bude ti účtovaný iba rozdiel. Ak urobíš downgrade, aktuálny plán zostáva v platnosti do konca obdobia.',
  'plans.faqCardDeclined': 'Moja karta bola zamietnutá, čo mám robiť?',
  'plans.faqCardDeclinedAnswer': 'Máš 7 dní na aktualizáciu svojej karty. Počas tohto obdobia všetky tvoje výhody zostanú funkčné. Po 7 dňoch sa plán vráti k bezplatnému.',
  'plans.faqDataSafe': 'Sú moje údaje v bezpečí?',
  'plans.faqDataSafeAnswer': 'Áno! Tvoje platobné údaje sú spracovávané s end-to-end šifrovaním. Neuchovávame číslo tvojej karty — len posledné 4 číslice na tvoju referenciu.',
